import { headers } from "next/headers";
import Database from "better-sqlite3";
import { auth } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Users live in Better Auth's `user` table; read them from the same database.
const db = new Database(process.env.DATABASE_PATH ?? "./auth.db", { readonly: true, fileMustExist: false });

type Row = { id: string; email: string; name: string; createdAt: string };

function toUser(r: Row): User {
  return { id: r.id, email: r.email, name: r.name, createdAt: String(r.createdAt).slice(0, 10) };
}

export async function listUsers(): Promise<User[]> {
  const rows = db.prepare('SELECT id, email, name, createdAt FROM "user" ORDER BY createdAt').all() as Row[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db.prepare('SELECT id, email, name, createdAt FROM "user" WHERE id = ?').get(id) as Row | undefined;
  return row && toUser(row);
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session) return undefined;
  const { id, email, name, createdAt } = session.user;
  return toUser({ id, email, name, createdAt: createdAt.toISOString() });
}
EOF
cat > src/components/auth-form.tsx <<'EOF'
"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { authClient } from "@/lib/auth-client";

export function AuthForm({ mode }: { mode: "sign-in" | "sign-up" }) {
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const isSignUp = mode === "sign-up";

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);
    setPending(true);
    const f = new FormData(e.currentTarget);
    const email = String(f.get("email"));
    const password = String(f.get("password"));
    const { error } = isSignUp
      ? await authClient.signUp.email({ email, password, name: String(f.get("name")) })
      : await authClient.signIn.email({ email, password });
    setPending(false);
    if (error) return setError(error.message ?? "Something went wrong");
    router.push("/dashboard");
    router.refresh();
  }

  const input = "w-full rounded border border-black/20 bg-transparent px-3 py-2 text-sm dark:border-white/20";

  return (
    <main className="mx-auto max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{isSignUp ? "Create account" : "Sign in"}</h1>
      <form onSubmit={onSubmit} className="mt-6 space-y-3">
        {isSignUp && <input name="name" placeholder="Name" required className={input} />}
        <input name="email" type="email" placeholder="Email" required autoComplete="email" className={input} />
        <input
          name="password"
          type="password"
          placeholder="Password (min 8 characters)"
          required
          minLength={8}
          autoComplete={isSignUp ? "new-password" : "current-password"}
          className={input}
        />
        {error && <p role="alert" className="text-sm text-red-600">{error}</p>}
        <button disabled={pending} className="w-full rounded bg-foreground px-3 py-2 text-sm text-background disabled:opacity-50">
          {isSignUp ? "Sign up" : "Sign in"}
        </button>
      </form>
      <button
        type="button"
        onClick={() => authClient.signIn.social({ provider: "google", callbackURL: "/dashboard" })}
        className="mt-3 w-full rounded border border-black/20 px-3 py-2 text-sm dark:border-white/20"
      >
        Continue with Google
      </button>
      <p className="mt-6 text-sm opacity-70">
        {isSignUp ? (
          <>Have an account? <Link href="/sign-in" className="underline">Sign in</Link></>
        ) : (
          <>No account? <Link href="/sign-up" className="underline">Sign up</Link></>
        )}
      </p>
    </main>
  );
}
EOF
