import { headers } from "next/headers";
import Database from "better-sqlite3";
import { auth } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Users live in Better Auth's `user` table; read them from the same database.
const db = new Database(process.env.DATABASE_PATH ?? "./auth.db", { readonly: true, fileMustExist: false });

type Row = { id: string; email: string; name: string; createdAt: string };

function toUser(r: Row): User {
  return { id: r.id, email: r.email, name: r.name, createdAt: String(r.createdAt).slice(0, 10) };
}

export async function listUsers(): Promise<User[]> {
  const rows = db.prepare('SELECT id, email, name, createdAt FROM "user" ORDER BY createdAt').all() as Row[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = db.prepare('SELECT id, email, name, createdAt FROM "user" WHERE id = ?').get(id) as Row | undefined;
  return row && toUser(row);
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session) return undefined;
  const { id, email, name, createdAt } = session.user;
  return toUser({ id, email, name, createdAt: createdAt.toISOString() });
}
